DOCUMENT();
############# # Load Macros #############
loadMacros( "PGstandard.pl", "PGML.pl", "AnswerFormatHelp.pl", "parserOneOf.pl", "contextFiniteSolutionSets.pl", "contextForm.pl", "ORCCA.pl", "PGcourse.pl", ); COMMENT('Authored in PreTeXt');
####### # Setup #######
do { ($m, $p, $q) = random_subset(3,-5..-2,2..5); $n = $m - $p*$q; ($b, $c, $e) = random_subset(3,-8..-1,1..8); $d = $m*$b - $c - $p*$e + list_random(-3..3,(0)x5); } until ($n != 0 && $d != 0); $x = list_random('a'..'n','p'..'z','A'..'D', 'F'..'N','P'..'T','V'..'Z'); Context()->variables->are($x => 'Real'); Context()->noreduce('(-x)+y', '(-x)-y'); $left = Formula("$m($x + $b) - ($n $x + $c)")->reduce; $right = Formula("$d + $p($e + $q $x)")->reduce; Context("FiniteSolutionSets"); $solution = ($d == $m*$b - $c - $p*$e) ? OneOf(Compute("R"), String("infinitely many solutions"))->cmp(typeMatch => Formula("{1}")) : String("no real solutions")->cmp(typeMatch => Formula("{1}"));
############################# # Exercise Group Introduction #############################
BEGIN_PGML Solve the equation for its variable.
END_PGML
###### # Body ######
BEGIN_PGML [`[$left]=[$right]`]
[_]{$solution}{16}
END_PGML
############# # End Problem #############
